import React from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { motion } from 'framer-motion';
import {
  FiHome,
  FiMessageCircle,
  FiUsers,
  FiUser,
  FiSettings,
  FiLogOut,
  FiMenu,
  FiX,
} from 'react-icons/fi';
import { logoutUser } from '../../store/slices/authSlice';

const Sidebar = () => {
  const dispatch = useDispatch();
  const location = useLocation();
  const { user } = useSelector((state) => state.auth);
  const { mobileMenuOpen } = useSelector((state) => state.ui);

  const handleLogout = () => {
    dispatch(logoutUser());
  };

  const navigation = [
    {
      name: 'Dashboard',
      href: '/dashboard',
      icon: FiHome,
      current: location.pathname === '/dashboard',
    },
    {
      name: 'Chat',
      href: '/chat',
      icon: FiMessageCircle,
      current: location.pathname.startsWith('/chat'),
    },
    {
      name: 'Doctors',
      href: '/doctors',
      icon: FiUsers,
      current: location.pathname === '/doctors',
    },
    {
      name: 'Profile',
      href: '/profile',
      icon: FiUser,
      current: location.pathname === '/profile',
    },
  ];

  return (
    <div className="flex flex-col h-full">
      {/* Logo */}
      <div className="flex items-center justify-between h-16 px-6 border-b border-gray-200">
        <div className="flex items-center">
          <div className="w-8 h-8 bg-gradient-to-r from-primary-600 to-health-600 rounded-lg flex items-center justify-center">
            <span className="text-white font-bold text-sm">HC</span>
          </div>
          <span className="ml-3 text-xl font-bold text-gray-900">Health Chat</span>
        </div>
        
        {/* Mobile close button */}
        <button
          onClick={() => dispatch({ type: 'ui/setMobileMenuOpen', payload: false })}
          className="lg:hidden p-2 rounded-md text-gray-400 hover:text-gray-600 hover:bg-gray-100"
        >
          <FiX className="h-5 w-5" />
        </button>
      </div>

      {/* User info */}
      <div className="px-6 py-4 border-b border-gray-200">
        <div className="flex items-center">
          <div className="w-10 h-10 bg-gradient-to-r from-primary-500 to-health-500 rounded-full flex items-center justify-center">
            <span className="text-white font-medium text-sm">
              {user?.fullName?.charAt(0)?.toUpperCase() || 'U'}
            </span>
          </div>
          <div className="ml-3">
            <p className="text-sm font-medium text-gray-900">{user?.fullName || 'User'}</p>
            <p className="text-xs text-gray-500 capitalize">{user?.userType || 'User'}</p>
          </div>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-4 py-4 space-y-1">
        {navigation.map((item) => {
          const Icon = item.icon;
          return (
            <NavLink
              key={item.name}
              to={item.href}
              className={({ isActive }) =>
                `group flex items-center px-3 py-2 text-sm font-medium rounded-lg transition-colors duration-200 ${
                  isActive
                    ? 'bg-primary-50 text-primary-700 border-r-2 border-primary-600'
                    : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                }`
              }
              onClick={() => {
                if (mobileMenuOpen) {
                  dispatch({ type: 'ui/setMobileMenuOpen', payload: false });
                }
              }}
            >
              <Icon
                className={`mr-3 h-5 w-5 ${
                  item.current ? 'text-primary-600' : 'text-gray-400 group-hover:text-gray-600'
                }`}
              />
              {item.name}
            </NavLink>
          );
        })}
      </nav>

      {/* Settings and Logout */}
      <div className="px-4 py-4 border-t border-gray-200 space-y-1">
        <button className="group flex items-center w-full px-3 py-2 text-sm font-medium text-gray-600 rounded-lg hover:bg-gray-50 hover:text-gray-900 transition-colors duration-200">
          <FiSettings className="mr-3 h-5 w-5 text-gray-400 group-hover:text-gray-600" />
          Settings
        </button>
        
        <button
          onClick={handleLogout}
          className="group flex items-center w-full px-3 py-2 text-sm font-medium text-red-600 rounded-lg hover:bg-red-50 transition-colors duration-200"
        >
          <FiLogOut className="mr-3 h-5 w-5 text-red-400 group-hover:text-red-600" />
          Logout
        </button>
      </div>
    </div>
  );
};

export default Sidebar;
